function getStatParts(str) {
    // Gets the prefix, number, and suffix from a string
    // 100% - {prefix: '', number: 55, suffix: '%'}
    // +60% - {prefix: '+', number: 60, suffix: '%'}
    // 2.5x - {prefix: '', number: 2.5, suffix: 'x'}
    // 100M - {prefix: '', number: 70, suffix: 'M'}
    // 100USD - {prefix: '', number: 100, suffix: 'USD'}
    
    // Don't parse strings with ranges like 5-10
    if (str.match(/\d+[-–—]\d+/)) return null

    // Get matching groups
    const match = str.match(/([^\d]*)(\d+(?:\.\d+)?)(.*)/)
    if (!match) return null

    return {
        prefix: match[1],
        number: parseFloat(match[2]),
        suffix: match[3]
    }
}

function initializeStatAnimations() {
    const stats = document.querySelectorAll('span[slot="statistics"]')

    stats.forEach((stat) => {
        const string = stat.textContent.trim()
        const statParts = getStatParts(string)
        const hiddenTabpanel = stat.closest('.cmp-tabs__tabpanel:not(.cmp-tabs__tabpanel--active)')

        // For debugging purposes
        // console.table({[`Stat ${i}: ${string}`]: statParts})

        // Don't animate if the string is empty, yes some stat blocks don't have a stat number :(
        if (!string) {
          return
        }

        // Don't animate if stats are within hidden tab panels
        if (hiddenTabpanel) {
          return
        }
        
        // Check for null statParts, just in case
        if (statParts === null) {
          return
        }

        const { prefix, number, suffix } = statParts

        // Check for NaN number, just in case
        if (isNaN(number)) {
          return
        }

        new CountUp(stat, number, {
            decimalPlaces: Number.isInteger(number) ? 0 : 1, // Support only one decimal place
            duration: 1.5,
            separator: '',
            prefix: prefix,
            suffix: suffix,
            enableScrollSpy: true,
            scrollSpyOnce: true,
        })
    })
}

window.addEventListener('load', function() {
  const languageCode = document.getElementsByName('languageCode')[0].content

  // Only animate numbers if language code is english
  if (languageCode === 'en') {
    initializeStatAnimations()
  }
})
